import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_OW": 64, "BLOCK_N": 32, "BLOCK_K": 16, "grf_mode": "256"},
        ),
    ],
    key=["D", "H", "W", "C_IN", "C_OUT", "OD", "OH", "OW"],
)
@triton.jit
def _conv3d_spatial_tiled(
    x_ptr,
    w_ptr,
    y_ptr,
    N_batch,
    D,
    H,
    W,
    OD,
    OH,
    OW,
    sx_n,
    sx_d,
    sx_h,
    sw_kd,
    sw_kh,
    sw_kw,
    sw_ci,
    sw_co,
    sy_n,
    sy_d,
    sy_h,
    BLOCK_OW: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    KD: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    PAD: tl.constexpr,
    C_IN: tl.constexpr,
    C_OUT: tl.constexpr,
    grf_mode: tl.constexpr,
):
    n = tl.program_id(0)
    pid_dh = tl.program_id(1)
    pid_wn = tl.program_id(2)

    od = pid_dh // OH
    oh = pid_dh % OH

    num_ow_tiles = tl.cdiv(OW, BLOCK_OW)
    pid_ow = pid_wn % num_ow_tiles
    pid_n = pid_wn // num_ow_tiles
    ow0 = pid_ow * BLOCK_OW

    acc = tl.zeros((BLOCK_OW, BLOCK_N), dtype=tl.float32)
    offs_ow = ow0 + tl.arange(0, BLOCK_OW)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)

    x_n_base = x_ptr + n.to(tl.int64) * sx_n

    for kd in range(KD):
        d_in = od + kd - PAD
        d_ok = (d_in >= 0) & (d_in < D)
        if d_ok:
            for kh in range(KH):
                h_in = oh + kh - PAD
                h_ok = (h_in >= 0) & (h_in < H)
                if h_ok:
                    x_dh_base = x_n_base + d_in * sx_d + h_in * sx_h

                    for kw in range(KW):
                        for c0 in range(0, C_IN, BLOCK_K):
                            offs_k = c0 + tl.arange(0, BLOCK_K)
                            input_w = offs_ow + kw - PAD
                            x_offsets = input_w[:, None] * C_IN + offs_k[None, :]
                            x_tile = tl.load(
                                x_dh_base + x_offsets,
                                mask=(input_w[:, None] >= 0)
                                & (input_w[:, None] < W)
                                & (offs_ow[:, None] < OW)
                                & (offs_k[None, :] < C_IN),
                                other=0.0,
                            )
                            w_offsets = (
                                kd * sw_kd
                                + kh * sw_kh
                                + kw * sw_kw
                                + offs_k[:, None] * sw_ci
                                + offs_n[None, :] * sw_co
                            )
                            w_tile = tl.load(
                                w_ptr + w_offsets,
                                mask=(offs_k[:, None] < C_IN)
                                & (offs_n[None, :] < C_OUT),
                                other=0.0,
                            )
                            acc = tl.dot(x_tile, w_tile, acc)

    y_dh_base = y_ptr + n.to(tl.int64) * sy_n + od * sy_d + oh * sy_h
    y_offsets = offs_ow[:, None] * C_OUT + offs_n[None, :]
    tl.store(
        y_dh_base + y_offsets,
        acc.to(tl.float16),
        mask=(offs_ow[:, None] < OW) & (offs_n[None, :] < C_OUT),
    )


class Model(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super(Model, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self._packed = False
        self._ks = kernel_size
        self._pad = padding

    def _pack_weights(self):
        w = self.conv_transpose3d.weight.data
        self._w_dhwio = (
            w.flip(2, 3, 4).permute(2, 3, 4, 0, 1).to(dtype=torch.float16).contiguous()
        )
        self._packed = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not self._packed:
            self._pack_weights()
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)

        x = x.to(memory_format=torch.channels_last_3d)
        x_ndhwc = x.permute(0, 2, 3, 4, 1)

        N_b, C_in, D, H, W = x.shape
        C_out = self._w_dhwio.shape[4]
        KS = self._ks
        PAD = KS - 1 - self._pad

        OD = D + 2 * PAD - KS + 1
        OH = H + 2 * PAD - KS + 1
        OW = W + 2 * PAD - KS + 1

        conv_out = torch.empty(
            (N_b, C_out, OD, OH, OW),
            device=x.device,
            dtype=torch.float16,
            memory_format=torch.channels_last_3d,
        )
        conv_ndhwc = conv_out.permute(0, 2, 3, 4, 1)

        def conv_grid(meta):
            return (
                N_b,
                OD * OH,
                triton.cdiv(OW, meta["BLOCK_OW"]) * triton.cdiv(C_out, meta["BLOCK_N"]),
            )

        _conv3d_spatial_tiled[conv_grid](
            x_ndhwc,
            self._w_dhwio,
            conv_ndhwc,
            N_b,
            D,
            H,
            W,
            OD,
            OH,
            OW,
            x_ndhwc.stride(0),
            x_ndhwc.stride(1),
            x_ndhwc.stride(2),
            self._w_dhwio.stride(0),
            self._w_dhwio.stride(1),
            self._w_dhwio.stride(2),
            self._w_dhwio.stride(3),
            self._w_dhwio.stride(4),
            conv_ndhwc.stride(0),
            conv_ndhwc.stride(1),
            conv_ndhwc.stride(2),
            KD=KS,
            KH=KS,
            KW=KS,
            PAD=PAD,
            C_IN=C_in,
            C_OUT=C_out,
        )

        return conv_out
